<?php
require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/functions.php';
$pageTitle='Data Siswa'; $q=trim($_GET['q']??'');
$sql='SELECT s.*, k.nama_kelas FROM siswa s LEFT JOIN kelas k ON k.id=s.id_kelas'; $params=[];
if($q!==''){ $sql.=' WHERE s.nama LIKE ? OR s.nis LIKE ?'; $params=['%'.$q.'%','%'.$q.'%']; }
$sql.=' ORDER BY s.id DESC'; $stmt=$pdo->prepare($sql); $stmt->execute($params); $rows=$stmt->fetchAll();
require __DIR__.'/../includes/header.php'; ?>
<div class="page-heading"><div><span class="eyebrow dark-eyebrow">DATA MANAGEMENT</span><h1>Data siswa</h1><p>Kelola informasi siswa yang terdaftar di sekolah.</p></div><a class="btn btn-primary" href="tambah.php">＋ Tambah siswa</a></div>
<section class="panel data-panel"><div class="panel-heading"><div><h2>Daftar siswa <span class="count-badge"><?= count($rows) ?></span></h2><p><?= $q!==''?'Hasil pencarian untuk “'.e($q).'”':'Semua data siswa' ?></p></div><form class="search-form" method="get"><span>⌕</span><input name="q" value="<?= e($q) ?>" placeholder="Cari nama atau NIS..."><button type="submit">Cari</button></form></div><div class="table-wrap"><table><thead><tr><th>NIS</th><th>Nama siswa</th><th>Jenis kelamin</th><th>Tanggal lahir</th><th>Kelas</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="6" class="empty-cell"><div class="empty-icon">⌕</div><b>Data belum ditemukan</b><p>Coba kata kunci lain atau tambahkan data siswa baru.</p></td></tr><?php else: foreach($rows as $r): ?><tr><td class="mono"><?= e($r['nis']) ?></td><td><div class="person-cell"><span class="person-avatar"><?= e(strtoupper(substr($r['nama'],0,1))) ?></span><b><?= e($r['nama']) ?></b></div></td><td><?= e($r['jenis_kelamin']) ?></td><td><?= e($r['tanggal_lahir'] ?: '-') ?></td><td><span class="class-chip"><?= e($r['nama_kelas'] ?: '-') ?></span></td><td><div class="row-actions"><a class="action-edit" href="edit.php?id=<?= (int)$r['id'] ?>">Edit</a><form method="post" action="hapus.php" onsubmit="return confirm('Hapus data siswa ini? Tindakan ini tidak bisa dibatalkan.');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="action-delete" type="submit">Hapus</button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div><div class="table-footer">Menampilkan <b><?= count($rows) ?></b> data siswa <span>Terakhir diperbarui: <?= date('d M Y') ?></span></div></section>
